{
  "headline": "Azithromycin is not on FDA's shortage list as of 2026-10-21; both Corvale sites use product from Proficient Rx LP (FEI 3011557028) last inspected VAI 2022-12-08",
  "headline_cites": ["D5", "E7", "E6"],
  "sentences": [
    {
      "text": "FDA's drug shortage list shows azithromycin is not listed as of 2026-10-21.",
      "cites": ["D5"]
    },
    {
      "text": "Corvale General and Corvale East both stock azithromycin 500 mg tablets labeled by Proficient Rx LP (NDC 71205067403).",
      "cites": ["E4", "E2"]
    },
    {
      "text": "The label identifies Proficient Rx LP as the registered plant with FEI 3011557028 performing relabel and repack operations.",
      "cites": ["E7"]
    },
    {
      "text": "FDA's most recent inspection of that plant ended 2022-12-08 and was classified VAI.",
      "cites": ["E6"]
    },
    {
      "text": "An earlier inspection ended 2015-10-22 and was also classified VAI.",
      "cites": ["E5"]
    },
    {
      "text": "Pfizer Inc. has a discontinuation posting for azithromycin tablets dated 2026-04-09, but that NDC differs from the product in use at Corvale.",
      "cites": ["E8"]
    },
    {
      "text": "The recommended action is to transfer 101 tablets of 500 mg from Corvale General to Corvale East, which would raise Corvale East's supply from 7.6 days to 14 days while leaving Corvale General with 17 days on hand.",
      "cites": ["D6"]
    }
  ]
}
